import React, { useState, useEffect, useMemo } from 'react';
import { useTable, useSortBy } from 'react-table';
import { searchTracks, getTrackDetails } from '../services/api';
import ArrowUpwardIcon from '@mui/icons-material/ArrowUpward';
import ArrowDownwardIcon from '@mui/icons-material/ArrowDownward';

const TrackSearch = ({ searchTerm }) => {
  const [filteredTracks, setFilteredTracks] = useState([]);
  const [trackDetails, setTrackDetails] = useState({});

  useEffect(() => {
    if (searchTerm) {
      searchTracks(searchTerm).then(async tracks => {
        setFilteredTracks(tracks);

        const detailsPromises = tracks.map(track =>
          getTrackDetails(track.id).then(details => ({ [track.id]: details }))
        );
        const detailsArray = await Promise.all(detailsPromises);
        setTrackDetails(Object.assign({}, ...detailsArray));
      }).catch(error => console.error('Error fetching tracks:', error));
    }
  }, [searchTerm]);

  const columns = useMemo(() => [
    { Header: 'Track Name', accessor: 'name', minWidth: 80 },
    { Header: 'Artist Name', accessor: 'artists[0].name', minWidth: 80 },
    { Header: 'Album Name', accessor: 'album.name', minWidth: 80 },
    { Header: 'Release Date', accessor: 'album.release_date', Cell: ({ value }) => value ? value.split('-')[0] : 'Unknown', minWidth: 80 },
    { Header: 'Tempo', accessor: row => trackDetails[row.id]?.tempo || '', minWidth: 80 },
    { Header: 'Key', accessor: row => trackDetails[row.id]?.key || '', minWidth: 80 },
    { Header: 'Danceability', accessor: row => trackDetails[row.id]?.danceability || 'Loading...', minWidth: 80 },
    { Header: 'Energy', accessor: row => trackDetails[row.id]?.energy || '', minWidth: 80 },
    { Header: 'Valence', accessor: row => trackDetails[row.id]?.valence || '', minWidth: 80 },
    { Header: 'Acousticness', accessor: row => trackDetails[row.id]?.acousticness || 'Loading...', minWidth: 80 },
    { Header: 'Instrumentalness', accessor: row => trackDetails[row.id]?.instrumentalness || 'Loading...', minWidth: 80 },
    { Header: 'Liveness', accessor: row => trackDetails[row.id]?.liveness || 'Loading...', minWidth: 80 },
    { Header: 'Genre', accessor: row => trackDetails[row.id]?.genres?.join(', ') || '', minWidth: 100 },
    {
      Header: 'Preview',
      accessor: 'preview', 
      Cell: ({ row }) => row.original.id ? (
        <iframe
          src={`https://open.spotify.com/embed/track/${row.original.id}`}
          width="100%"
          height="80"
          allow="encrypted-media"
          style={{ border: 'none' }}
        ></iframe>
      ) : 'No Preview',
      minWidth: 240
    },
  ], [trackDetails]);

  const data = useMemo(() => filteredTracks, [filteredTracks]);
  const { getTableProps, getTableBodyProps, headerGroups, rows, prepareRow } = useTable({ columns, data }, useSortBy);

  return filteredTracks.length > 0 ? (
    <table {...getTableProps()} style={{ width: '100%', marginTop: '20px', borderCollapse: 'collapse' }} className="results-table">
      <thead>
        {headerGroups.map(headerGroup => (
          <tr {...headerGroup.getHeaderGroupProps()} style={{ backgroundColor: '#00b4db', color: 'white' }}>
            {headerGroup.headers.map(column => (
              <th {...column.getHeaderProps(column.getSortByToggleProps())} style={{ padding: '10px', borderBottom: '1px solid #ddd', minWidth: column.minWidth }}>
                {column.render('Header')}
                {column.isSorted ? (column.isSortedDesc ? <ArrowDownwardIcon /> : <ArrowUpwardIcon />) : null}
              </th>
            ))}
          </tr>
        ))}
      </thead>
      <tbody {...getTableBodyProps()}>
        {rows.map((row, index) => {
          prepareRow(row);
          return (
            <tr
              {...row.getRowProps()}
              style={{
                backgroundColor: index % 2 === 0 ? '#f9f9f9' : 'white',
                color: '#606060',
                fontFamily: 'Arial, sans-serif',
                borderBottom: '1px solid #ddd'
              }}
            >
              {row.cells.map(cell => (
                <td {...cell.getCellProps()} style={{ padding: '10px', borderBottom: '1px solid #ddd', minWidth: cell.column.minWidth }}>
                  {cell.render('Cell')}
                </td>
              ))}
            </tr>
          );
        })}
      </tbody>
    </table>
  ) : <p>No results found</p>;
};

export default TrackSearch;
